const test = require('node:test');
const assert = require('node:assert/strict');
const { retryDelayMs } = require('../src/retry-delay.cjs');

test("delay seconds are measured from receipt and converted to milliseconds", () => {
  const receivedAt = Date.parse('2026-07-18T09:00:00.000Z');
  assert.equal(retryDelayMs('17', receivedAt), 17000);
  assert.equal(retryDelayMs('0', receivedAt), 0);
  assert.equal(retryDelayMs('007', receivedAt), 7000);
});

test("HTTP dates denote an absolute retry time", () => {
  assert.equal(retryDelayMs('Sat, 18 Jul 2026 09:00:03 GMT', Date.parse('2026-07-18T09:00:00.250Z')), 2750);
  assert.equal(retryDelayMs('Sat, 18 Jul 2026 09:00:00 GMT', Date.parse('2026-07-18T09:00:00.000Z')), 0);
  assert.equal(retryDelayMs('Sat, 18 Jul 2026 08:59:59 GMT', Date.parse('2026-07-18T09:00:00.000Z')), 0);
});

